// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Enchanted Goblet', price: 49.99 },
  { id: '2', name: 'Raven Feather Quill', price: 12.50 }
];

const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const renderCheckout = (items = mockItems) => {
  return render(
    <CartProvider value={{ items, total: 62.49, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout flow through confirmation', async () => {
    const user = userEvent.setup();
    renderCheckout();

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
    await user.type(screen.getByLabelText(/city/i), 'Avalon');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Morgan le Fay');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/enchanted goblet/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
    });
  });
});

describe('Checkout - Form Validation', () => {
  it('displays inline errors for empty shipping fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error Handling', () => {
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    // ... navigate to review step

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent('Card declined');
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout([]);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});
